370		b, err := GetVersion(dir, BuiltinVersionID)
371		if err != nil {
372			t.Fatal(err)
373		}
374		if b.Rules.Sandwich != (SandwichRule{Enabled: true, Severity: 3}) ||
375			b.Rules.Displacement != (DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2}) {
