544		if _, err := EnableVersion(dir, "strict"); err != nil {
545			t.Fatal(err)
546		}
547		second := replay(t, dir, sandwichInput)
548		if second[0].Version.ID != BuiltinVersionID {
549			t.Fatalf("reimport must return the original report, got version %+v", second[0].Version)
550		}
551		if len(second[0].Findings) != 1 || second[0].Findings[0].Severity != 3 {
552			t.Fatalf("reimport findings changed: %+v", second[0].Findings)
553		}
554		data, err := readArchive(dir)
555		if err != nil {
556			t.Fatal(err)
557		}
558		if len(data.Records) != 1 {
559			t.Fatalf("reimport added records: %d", len(data.Records))
560		}
561	}
