563	func TestCompareVersions(t *testing.T) {
564		dir := t.TempDir()
565		// 0xza/0xzb: displacement under builtin (99 > 2*10), gone under strict (99 < 5*10... wait 5*10=50, 99>50 flagged).
566		// Use front gas 40 vs victim 10: flagged by builtin (40>20), not by strict (40<50).
567		input := `{"chainId":"1","blockHash":"0xcmp","blockNumber":7,"swaps":[` +
568			`{"TxHash":"0xfa","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":40,"Index":0},` +
569			`{"TxHash":"0xva","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
570			`{"TxHash":"0xfb","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":90,"Index":2},` +
571			`{"TxHash":"0xvb","Pool":"p2","Trader":"user","In":1,"Out":1,"GasPrice":10,"Index":3},` +
572			`{"TxHash":"0xbb","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":80,"Index":4}]}`
573		original := replay(t, dir, input)
574		if len(original[0].Findings) != 2 {
575			t.Fatalf("setup: got %d findings, want 2", len(original[0].Findings))
576		}
577		register(t, dir, strictSpec)
578	
579		result, err := Compare(dir, "1", "0xcmp", "strict")
580		if err != nil {
581			t.Fatal(err)
582		}
583		if result.OriginalVersion != BuiltinVersion() {
584			t.Fatalf("original version wrong: %+v", result.OriginalVersion)
585		}
586		if result.ComparedVersion.ID != "strict" || result.ComparedVersion.Rules.Displacement.Multiplier != 5 {
587			t.Fatalf("compared version wrong: %+v", result.ComparedVersion)
588		}
589		if len(result.Swaps) != 5 {
590			t.Fatalf("raw swap evidence missing: %+v", result.Swaps)
591		}
592		// 0xva: displacement under builtin, nothing under strict -> removed.
593		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xva" {
594			t.Fatalf("removed = %+v", result.Removed)
595		}
596		// 0xvb: sandwich under both, severity 3 -> 5: changed only, not added+removed.
597		if len(result.Changed) != 1 || result.Changed[0].TxHash != "0xvb" {
598			t.Fatalf("changed = %+v", result.Changed)
599		}
600		if result.Changed[0].Original.Severity != 3 || result.Changed[0].Compared.Severity != 5 {
601			t.Fatalf("change detail wrong: %+v", result.Changed[0])
602		}
603		if len(result.Added) != 0 {
604			t.Fatalf("added = %+v", result.Added)
605		}
606		// Both full conclusion sets are present.
607		if len(result.OriginalFindings) != 2 || len(result.ComparedFindings) != 1 {
608			t.Fatalf("findings sets wrong: %+v / %+v", result.OriginalFindings, result.ComparedFindings)
609		}
610		// Compare must not modify the archived report or the enabled version.
611		after, err := Query(dir, "1", "0xcmp")
612		if err != nil {
613			t.Fatal(err)
614		}
615		if after.Version.ID != BuiltinVersionID || len(after.Findings) != 2 || after.Findings[1].Severity != 2 {
616			t.Fatalf("compare modified the archived report: %+v", after)
617		}
618		_, enabled, _ := ListVersions(dir)
619		if enabled != BuiltinVersionID {
620			t.Fatalf("compare changed enabled version to %q", enabled)
621		}
622	}
