87		fmt.Println("  reviews history <archive-dir> <chainId> <blockHash> <txHash> <kind>")
88		fmt.Println("                                           query a conclusion's current review and revisions")
89		fmt.Println("  reviews evaluate <archive-dir> <chainId> <startHeight> <endHeight> <version-id>")
