125			fmt.Fprintln(os.Stderr, "usage: mevwatch rules <list|show|register|enable> ...")
126			os.Exit(2)
127		}
128		switch args[0] {
129		case "list":
130			if len(args) != 2 {
131				fmt.Fprintln(os.Stderr, "usage: mevwatch rules list <archive-dir>")
132				os.Exit(2)
133			}
134			versions, enabled, err := mevwatch.ListVersions(args[1])
135			if err != nil {
136				fmt.Fprintf(os.Stderr, "rules list: %v\n", err)
137				os.Exit(1)
138			}
139			writeJSON(struct {
140				Enabled  string                 `json:"enabled"`
141				Versions []mevwatch.RuleVersion `json:"versions"`
142			}{Enabled: enabled, Versions: versions})
143		case "show":
144			if len(args) != 3 {
145				fmt.Fprintln(os.Stderr, "usage: mevwatch rules show <archive-dir> <version-id>")
146				os.Exit(2)
147			}
148			version, err := mevwatch.GetVersion(args[1], args[2])
149			if err != nil {
150				fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
151				os.Exit(1)
152			}
153			writeJSON(version)
154		case "register":
155			if len(args) != 3 {
156				fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
157				os.Exit(2)
158			}
159			var raw []byte
